import{_ as a,o as t,c as s,a2 as i}from"./chunks/framework.dWYrTn1b.js";const m=JSON.parse(`{"title":"Component libraries","description":"Where a program's parts and its world's objects and environments come from, how a component library is laid out, and how the compiler picks an entry by its id.","frontmatter":{"title":"Component libraries","description":"Where a program's parts and its world's objects and environments come from, how a component library is laid out, and how the compiler picks an entry by its id."},"headers":[],"relativePath":"guide/basics/libraries.md","filePath":"guide/basics/libraries.md"}`),o={name:"guide/basics/libraries.md"};function r(n,e,l,h,d,p){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="component-libraries" tabindex="-1">Component libraries <a class="header-anchor" href="#component-libraries" aria-label="Permalink to &quot;Component libraries&quot;">​</a></h1><p>Every <code>ref</code> in a program names an entry of a component library: a part of the robot, an object the world places, or an environment a scenario takes. A library is a plain directory the compiler reads with <code>--library</code>; there is no install step and no default location.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mobiledsl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> robot.core</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> robot.world</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> robot.task</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --library</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> path/to/library</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --check</span></span></code></pre></div><h2 id="what-is-inside" tabindex="-1">What is inside <a class="header-anchor" href="#what-is-inside" aria-label="Permalink to &quot;What is inside&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;library&gt;/</span></span>
<span class="line"><span>├── library.yaml                 the library&#39;s name and the ids of its parts</span></span>
<span class="line"><span>└── parts/&lt;part-id&gt;/</span></span>
<span class="line"><span>    ├── component.yaml           the part: shape, mass, mating points, what it can be used as</span></span>
<span class="line"><span>    └── assets/                  the mesh the part is drawn with</span></span></code></pre></div><p>A part the <code>library.yaml</code> does not list does not exist to the compiler. Each part&#39;s <code>component.yaml</code> states:</p><ul><li>its category: <code>chassis</code>, <code>wheel</code>, <code>sensor</code> or <code>attachment</code>;</li><li>its visual mesh, and a collision box that stands in for it;</li><li>its mass, centre of mass and inertia, with where the numbers came from;</li><li>its connectors, the named points where it mates with other parts;</li><li>its profiles, the component types it can be used as, such as <code>Lidar</code> or <code>Diff_two_caster</code>.</li></ul><p><a href="./../../reference/library.html">The library format</a> specifies every field.</p><h2 id="how-a-part-is-picked" tabindex="-1">How a part is picked <a class="header-anchor" href="#how-a-part-is-picked" aria-label="Permalink to &quot;How a part is picked&quot;">​</a></h2><p><code>Lidar top_lidar(ref = &quot;lidar_ld06&quot;, ...)</code> asks for the part <code>lidar_ld06</code>. The compiler checks that:</p><ul><li>exactly one of the given libraries has a part with that id;</li><li>the part&#39;s category fits the component type, a sensor for <code>Lidar</code>;</li><li>the part lists the type under its profiles.</li></ul><p>Each failure is its own diagnostic at the component.</p><h2 id="objects-for-the-world" tabindex="-1">Objects for the world <a class="header-anchor" href="#objects-for-the-world" aria-label="Permalink to &quot;Objects for the world&quot;">​</a></h2><p>A library also holds objects, the things a world places: a crate, a table, a ramp. An object is an entry like a part, listed in <code>library.yaml</code> and declared in <code>parts/&lt;id&gt;/component.yaml</code>, with the category <code>object</code>. It states the mesh it is shown by and the shapes it collides by, and none of what a part states to be assembled and moved: no mass, no connectors, no profiles. An object is not bought, so it states no price either; its mesh may be a model that a collection publishes for simulators, and its entry then says where the model came from and under which licence.</p><p><code>Obstacle table(ref = &quot;work_table&quot;, ...)</code> in a <code>.world</code> file asks for the object <code>work_table</code>, and exactly one of the given libraries must have it. An id is a part&#39;s or an object&#39;s: a part named in a world, or an object named on a robot, is refused with what the entry is.</p><p>A library holds whole environments too, with the category <code>environment</code>: a room or a hall as its floor and a list of entities, each a primitive or one of the library&#39;s objects, written with the names a <code>.world</code> file uses. <code>Scenario room(ref = &quot;room_6x4&quot;)</code> takes it, and its entities become the scenario&#39;s.</p><p><a href="./world.html#objects-from-a-library">The world</a> shows how an object is placed and an environment taken, and <a href="./../advanced/your-own-part.html#an-object-for-the-world">Adding your own part</a> how each is declared.</p><h2 id="several-libraries" tabindex="-1">Several libraries <a class="header-anchor" href="#several-libraries" aria-label="Permalink to &quot;Several libraries&quot;">​</a></h2><p>Repeat <code>--library</code> to use several. A part must be in exactly one of them, so a library you keep next to your program can add parts to a shared catalog but not shadow one of its parts.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mobiledsl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> robot.core</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> robot.world</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> robot.task</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --library</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> path/to/catalog</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --library</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my_parts</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --check</span></span></code></pre></div><h2 id="incomplete-parts" tabindex="-1">Incomplete parts <a class="header-anchor" href="#incomplete-parts" aria-label="Permalink to &quot;Incomplete parts&quot;">​</a></h2><p>A shared catalog may hold a few parts that are not fully declared. Such a part is left out with a warning, and the rest of the library still serves every program that uses its complete parts. A program that names the part gets an error that says why it could not be loaded.</p><h2 id="meshes-in-the-output" tabindex="-1">Meshes in the output <a class="header-anchor" href="#meshes-in-the-output" aria-label="Permalink to &quot;Meshes in the output&quot;">​</a></h2><p>The compiler never opens a mesh; it copies each part&#39;s visual mesh, and each placed object&#39;s, into the output directory for the simulator to draw. The whole directory the mesh lies in is copied, since a mesh may keep its buffers, materials and textures in files beside it: put those there, and nothing else.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><p><a href="./diagnostics.html">Reading diagnostics</a> shows how the compiler reports problems. To add a part of your own, see <a href="./../advanced/your-own-part.html">Adding your own part</a>.</p>`,26)])])}const b=a(o,[["render",r]]);export{m as __pageData,b as default};
